import pytesseract
from openpyxl import Workbook
from PIL import Image, ImageFilter, ImageOps

IMG_DIR = "/app/workspace/dataset/img"
OUT_XLSX = "/app/workspace/stat_ocr.xlsx"

PRIORITY_KEYWORDS = [
    ("GRAND TOTAL",),
    ("TOTAL RM", "TOTAL: RM"),
    ("TOTAL AMOUNT",),
    ("TOTAL", "AMOUNT", "TOTAL DUE", "AMOUNT DUE", "BALANCE DUE",
     "NETT TOTAL", "NET TOTAL"),
]
EXCLUSION_KEYWORDS = [
    "SUBTOTAL", "SUB TOTAL", "TAX", "GST", "SST",
    "DISCOUNT", "CHANGE", "CASH TENDERED",
]

AMOUNT_RE = re.compile(r"(?<![A-Za-z0-9.])(\d{1,3}(?:,\d{3})*\.\d{2}|\d+\.\d{2})(?![0-9])")
DATE_RES = [
    re.compile(r"(\d{1,2})[/\-.](\d{1,2})[/\-.](\d{2,4})"),
    re.compile(r"(\d{4})[/\-.](\d{1,2})[/\-.](\d{1,2})"),
]


def ocr_passes(img):
    passes = []
    passes.append(pytesseract.image_to_string(img, lang="eng"))
    g = ImageOps.autocontrast(ImageOps.grayscale(img))
    passes.append(pytesseract.image_to_string(g, lang="eng", config="--psm 6"))
    passes.append(pytesseract.image_to_string(g.filter(ImageFilter.SHARPEN),
                                              lang="eng", config="--psm 6"))
    passes.append(pytesseract.image_to_string(g, lang="eng", config="--psm 4"))
    if min(img.size) < 1200:
        big = img.resize((img.size[0] * 2, img.size[1] * 2))
        big = ImageOps.autocontrast(ImageOps.grayscale(big))
        passes.append(pytesseract.image_to_string(big, lang="eng", config="--psm 6"))
        passes.append(pytesseract.image_to_string(big, lang="eng", config="--psm 4"))
    return [p for p in passes if p and p.strip()]


def normalize_amount(s):
    if s is None:
        return None
    s = str(s).replace(",", "").strip()
    m = re.search(r"(\d+)\.(\d{1,2})", s)
    if not m:
        return None
    whole, frac = m.group(1), m.group(2).ljust(2, "0")[:2]
    return f"{int(whole)}.{frac}"


def line_has_exclusion(line_upper):
    return any(k in line_upper for k in EXCLUSION_KEYWORDS)


def find_amount_on_line(line):
    nums = AMOUNT_RE.findall(line)
    return nums[-1] if nums else None


def extract_total_from_text(text):
    lines = [ln for ln in text.splitlines() if ln.strip()]
    uppers = [ln.upper() for ln in lines]

    for group in PRIORITY_KEYWORDS:
        best = None
        for i, up in enumerate(uppers):
            if any(k in up for k in group):
                if line_has_exclusion(up):
                    continue
                amt = find_amount_on_line(lines[i])
                if amt is None and i + 1 < len(lines):
                    amt = find_amount_on_line(lines[i + 1])
                if amt is not None:
                    best = amt  # last matching wins (bottom of receipt)
        if best is not None:
            return normalize_amount(best)
    return None


def valid_date(y, m, d):
    try:
        y, m, d = int(y), int(m), int(d)
    except ValueError:
        return None
    if y < 100:
        y += 2000
    if not (2000 <= y <= 2035 and 1 <= m <= 12 and 1 <= d <= 31):
        return None
    return f"{y:04d}-{m:02d}-{d:02d}"


def extract_date_from_text(text):
    lines = [ln for ln in text.splitlines() if ln.strip()]
    labeled = []
    unlabeled = []
    for i, ln in enumerate(lines):
        up = ln.upper()
        is_labeled = any(lbl in up for lbl in ("DATE", "DATED", "BIZDATE", "DOC DATE",
                                                "INVOICE DATE", "BILL DT", "BILL DATE"))
        for pat in DATE_RES:
            for m in pat.finditer(ln):
                g = m.groups()
                if len(g[0]) == 4:  # YYYY-MM-DD
                    date = valid_date(g[0], g[1], g[2])
                else:  # DD/MM/YYYY (receipts in this set are Malaysian: dd/mm/yyyy)
                    date = valid_date(g[2], g[1], g[0])
                if date:
                    (labeled if is_labeled else unlabeled).append((i, date))
    if labeled:
        return labeled[0][1]
    if unlabeled:
        return unlabeled[0][1]
    return None


def vote(candidates):
    vals = [c for c in candidates if c is not None]
    if not vals:
        return None
    return Counter(vals).most_common(1)[0][0]


def process_image(path):
    img = Image.open(path)
    texts = ocr_passes(img)
    dates = [extract_date_from_text(t) for t in texts]
    totals = [extract_total_from_text(t) for t in texts]
    return vote(dates), vote(totals)


def main():
    files = sorted(f for f in os.listdir(IMG_DIR)
                   if f.lower().endswith((".png", ".jpg", ".jpeg")))
    wb = Workbook()
    ws = wb.active
    ws.title = "results"
    ws.append(["filename", "date", "total_amount"])
    for fname in files:
        date, total = process_image(os.path.join(IMG_DIR, fname))
        ws.append([fname, date, total])
        print(f"{fname}\t{date}\t{total}")
    wb.save(OUT_XLSX)
    print(f"Saved {OUT_XLSX}")


if __name__ == "__main__":
    main()
