        big = img.resize((img.size[0] * 2, img.size[1] * 2))
        big = ImageOps.autocontrast(ImageOps.grayscale(big))
        passes.append(pytesseract.image_to_string(big, lang="eng", config="--psm 6"))
        passes.append(pytesseract.image_to_string(big, lang="eng", config="--psm 4"))
    return [p for p in passes if p and p.strip()]


def normalize_amount(s):
    if s is None:
        return None
    s = str(s).replace(",", "").strip()
    m = re.search(r"(\d+)\.(\d{1,2})", s)
    if not m:
        return None
    whole, frac = m.group(1), m.group(2).ljust(2, "0")[:2]
    return f"{int(whole)}.{frac}"


def norm_match(s):
    """Collapse punctuation to spaces for substring matching."""
    return re.sub(r"[^A-Z0-9]+", " ", s.upper()).strip()


def line_has_exclusion(line_upper):
    norm = " " + norm_match(line_upper) + " "
    # "Total Sales (Inclusive of GST)" is the final payable total, not a tax line.
    if ("INCLUSIVE" in norm or "INCLUDING" in norm) and "TOTAL" in norm:
        return False
    for kw in EXCLUSION_KEYWORDS:
        if (" " + kw + " ") in norm or norm.startswith(kw + " ") or norm.endswith(" " + kw) or norm == kw:
            return True
    return False


def line_matches_keyword(line_upper, keywords):
    norm = " " + norm_match(line_upper) + " "
    for kw in keywords:
