    return False


def find_amount_on_line(line):
    nums = AMOUNT_RE.findall(line)
    return nums[-1] if nums else None


def is_keyword_only_line(line, keywords):
    """True when the line is essentially just the keyword (allow trailing ':')"""
    norm = norm_match(line)
    for kw in keywords:
        if norm == kw or norm == kw.replace(" ", ""):
            return True
    return False


def extract_total_from_text(text):
    lines = [ln for ln in text.splitlines() if ln.strip()]
    uppers = [ln.upper() for ln in lines]

    for group in PRIORITY_KEYWORDS:
        best = None
        # Primary pass: same-line amount
        for i, up in enumerate(uppers):
            if not line_matches_keyword(up, group):
                continue
            if line_has_exclusion(up):
                continue
            amt = find_amount_on_line(lines[i])
            if amt is not None:
                best = amt  # last match wins (bottom of receipt)
        if best is not None:
            return normalize_amount(best)
        # Fallback: keyword-only line, use next line
        for i, up in enumerate(uppers):
            if not line_matches_keyword(up, group):
                continue
            if line_has_exclusion(up):
                continue
            if not is_keyword_only_line(lines[i], group):
                continue
            if i + 1 < len(lines):
                amt = find_amount_on_line(lines[i + 1])
                if amt is not None:
