    return False


def line_matches_keyword(norm, keywords):
    padded = " " + norm + " "
    for kw in keywords:
        if (" " + kw + " ") in padded:
            return True
    return False


def find_amount_on_line(line):
    nums = AMOUNT_RE.findall(line)
    return nums[-1] if nums else None


def is_keyword_only_line(norm, keywords):
    for kw in keywords:
        if norm == kw or norm == kw.replace(" ", ""):
            return True
    return False


def line_starts_with_digit(line):
    for ch in line.lstrip():
        return ch.isdigit()
    return False


def truncate_at_stop(lines):
    for i, ln in enumerate(lines):
        if i < STOP_MIN_LINE:
            continue
        norm = norm_match(ln)
        for sp in STOP_PATTERNS:
            if sp in norm:
                return lines[:i]
    return lines


def extract_total_from_text(text):
    all_lines = [ln for ln in text.splitlines() if ln.strip()]
    lines = truncate_at_stop(all_lines)
    norms = [norm_match(ln) for ln in lines]

    for group in PRIORITY_KEYWORDS:
        best = None
        for i, norm in enumerate(norms):
            if not line_matches_keyword(norm, group):
                continue
            if line_has_exclusion(norm):
                continue
            # Skip item lines that start with a digit (e.g. "2 Type: 1 Total 11.60").
            if line_starts_with_digit(lines[i]):
                continue
            amt = find_amount_on_line(lines[i])
            if amt is not None:
                best = amt
        if best is not None:
            return normalize_amount(best)
        for i, norm in enumerate(norms):
            if not line_matches_keyword(norm, group):
                continue
            if line_has_exclusion(norm):
                continue
            if not is_keyword_only_line(norm, group):
                continue
            if i + 1 < len(lines):
                amt = find_amount_on_line(lines[i + 1])
                if amt is not None:
                    best = amt
        if best is not None:
            return normalize_amount(best)
    return None


def valid_date(y, m, d):
    try:
        y, m, d = int(y), int(m), int(d)
    except ValueError:
        return None
    if y < 100:
        y += 2000
    if not (2000 <= y <= 2035 and 1 <= m <= 12 and 1 <= d <= 31):
        return None
    return f"{y:04d}-{m:02d}-{d:02d}"


def extract_date_from_text(text):
    lines = [ln for ln in text.splitlines() if ln.strip()]
    labeled = []
    unlabeled = []
    for i, ln in enumerate(lines):
        up = ln.upper()
        is_labeled = any(lbl in up for lbl in LABEL_TOKENS)
        bucket = labeled if is_labeled else unlabeled
        for m in MONTH_RE.finditer(ln):
            d, mon, y = m.group(1), m.group(2).upper(), m.group(3)
            mm = MONTHS.get(mon[:3]) or MONTHS.get(mon)
            date = valid_date(y, mm, d) if mm else None
            if date:
                bucket.append((i, date))
        for pat in DATE_RES:
            for m in pat.finditer(ln):
                g = m.groups()
                if len(g[0]) == 4:
                    date = valid_date(g[0], g[1], g[2])
                else:
                    date = valid_date(g[2], g[1], g[0])  # dd/mm/yyyy Malaysian
                if date:
                    bucket.append((i, date))
    if labeled:
        return labeled[0][1]
    if unlabeled:
        return unlabeled[0][1]
    return None


def vote(candidates):
    vals = [c for c in candidates if c is not None]
    if not vals:
        return None
    return Counter(vals).most_common(1)[0][0]


def process_image(path):
    img = Image.open(path)
    texts = ocr_passes(img)
    dates = [extract_date_from_text(t) for t in texts]
    totals = [extract_total_from_text(t) for t in texts]
    return vote(dates), vote(totals)


def main():
    files = sorted(f for f in os.listdir(IMG_DIR)
                   if f.lower().endswith((".png", ".jpg", ".jpeg")))
    wb = Workbook()
    ws = wb.active
    ws.title = "results"
    ws.append(["filename", "date", "total_amount"])
    for fname in files:
        date, total = process_image(os.path.join(IMG_DIR, fname))
        ws.append([fname, date, total])
        print(f"{fname}\t{date}\t{total}")
    wb.save(OUT_XLSX)
    print(f"Saved {OUT_XLSX}")


if __name__ == "__main__":
    main()
